<script setup lang="ts">import {ref,watch} from 'vue';import {api} from '../../api';import {locale,t} from '../../locales';import '../../styles/app.scss';const q=ref('');const items=ref<any[]>([]);const loading=ref(false);async function search(){if(!q.value.trim()){items.value=[];return}loading.value=true;try{items.value=await api.news(q.value.trim())}catch{uni.showToast({title:t('搜索失败'),icon:'none'})}finally{loading.value=false}}watch(locale,()=>{if(q.value.trim())search()})</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('搜索')}}</text></view><view class="inner-main"><view class="search-bar"><text>⌕</text><input v-model="q" focus :placeholder="t('搜索新闻、币种、项目')" @confirm="search"/><text class="search-submit" @click="search">{{t('搜索')}}</text></view><view v-if="!items.length" class="inner-card hot-search"><text class="form-label">{{t('热门搜索')}}</text><view class="inner-tabs"><text class="inner-tab" v-for="x in ['BTC','ETH','ETF','美联储']" :key="x" @click="q=x;search()">{{x==='美联储'?t('美联储'):x}}</text></view></view><view v-for="item in items" :key="item.id" class="list-card" @click="uni.navigateTo({url:'/pages/detail/news?id='+item.id})"><view class="list-icon">▤</view><view class="list-copy"><text class="list-title">{{item.title}}</text><text class="list-meta">{{item.source}} · {{item.time}}</text></view><text class="list-arrow">›</text></view></view></view></template>
<style scoped>.search-bar{display:flex;align-items:center;gap:10rpx;height:70rpx;padding:0 16rpx;border:1rpx solid var(--cf-line);border-radius:12rpx;background:#fff;color:var(--cf-soft)}.search-bar input{flex:1;min-width:0;height:100%;font-size:21rpx}.search-submit{color:var(--cf-brand);font-size:20rpx;font-weight:700}.hot-search{margin-top:18rpx}.hot-search .inner-tabs{margin:14rpx 0 0}</style>
